A complete CommunityToolkit implementation is:

```csharp
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;

public partial class ProductDetailViewModel : ObservableObject
{
    private readonly IProductService _products;

    public ProductDetailViewModel(IProductService products)
        => _products = products;

    [ObservableProperty]
    private string name = string.Empty;

    [ObservableProperty]
    private decimal price;

    [ObservableProperty]
    private bool isAvailable;

    [RelayCommand]
    private async Task LoadAsync()
    {
        var product = await _products.GetProductAsync();
        Name = product.Name;
        Price = product.Price;
        IsAvailable = product.IsAvailable;
    }
}
```

ObservableObject supplies INotifyPropertyChanged, and each ObservableProperty generates a notifying public property. RelayCommand turns LoadAsync into an asynchronous LoadCommand, so the UI remains responsive while data is fetched.
